/**
 * MCP Config Path Discovery Cache
 *
 * Persists discovered AI client config paths to ~/.vreko/mcp-configs/paths.json
 * so that detection is instant on subsequent runs instead of probing all candidates.
 *
 * Cache TTL is 7 days  -  long enough to avoid redundant I/O, short enough to
 * pick up path changes when clients update their storage layout.
 *
 * @packageDocumentation
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

// =============================================================================
// TYPES
// =============================================================================

interface CachedPath {
	/** Absolute path that was verified to exist */
	path: string;
	/** ISO timestamp when the path was last confirmed */
	discoveredAt: string;
	/** OS platform string (darwin/win32/linux) */
	platform: string;
}

interface PathCacheFile {
	version: 1;
	/** client name → confirmed path entry */
	discovered: Record<string, CachedPath>;
}

// =============================================================================
// CONSTANTS
// =============================================================================

const CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 days

function getCacheFilePath(): string {
	return join(homedir(), ".vreko", "mcp-configs", "paths.json");
}

// =============================================================================
// READ / WRITE
// =============================================================================

function readCache(): PathCacheFile {
	try {
		const raw = readFileSync(getCacheFilePath(), "utf-8");
		const parsed = JSON.parse(raw) as PathCacheFile;
		if (parsed.version === 1 && typeof parsed.discovered === "object") {
			return parsed;
		}
	} catch {
		// File missing or corrupt  -  return empty cache
	}
	return { version: 1, discovered: {} };
}

function writeCache(cache: PathCacheFile): void {
	try {
		const dir = join(homedir(), ".vreko", "mcp-configs");
		mkdirSync(dir, { recursive: true });
		writeFileSync(getCacheFilePath(), JSON.stringify(cache, null, 2));
	} catch {
		// Non-fatal  -  cache write failure silently ignored
	}
}

// =============================================================================
// PUBLIC API
// =============================================================================

/**
 * Look up a cached config path for a client.
 * Returns the path if it was cached recently AND the file still exists.
 * Returns null if cache miss, expired, or the cached path no longer exists.
 */
export function getCachedPath(clientName: string): string | null {
	const cache = readCache();
	const entry = cache.discovered[clientName];
	if (!entry) {
		return null;
	}

	// Expire stale entries
	const age = Date.now() - new Date(entry.discoveredAt).getTime();
	if (age > CACHE_TTL_MS) {
		return null;
	}

	// Verify the file still exists (client may have been uninstalled)
	if (!existsSync(entry.path)) {
		// Evict the stale entry
		delete cache.discovered[clientName];
		writeCache(cache);
		return null;
	}

	return entry.path;
}

/**
 * Record a successfully discovered path for a client.
 * Called by detectAIClients after confirming a candidate exists.
 */
export function setCachedPath(clientName: string, configPath: string): void {
	const cache = readCache();
	cache.discovered[clientName] = {
		path: configPath,
		discoveredAt: new Date().toISOString(),
		platform: process.platform,
	};
	writeCache(cache);
}

/**
 * Evict a client's cached path (e.g. after `vreko mcp unlink`).
 */
export function evictCachedPath(clientName: string): void {
	const cache = readCache();
	if (cache.discovered[clientName]) {
		delete cache.discovered[clientName];
		writeCache(cache);
	}
}

/**
 * Return the full contents of the cache for diagnostics / `vreko mcp scan`.
 */
export function getAllCachedPaths(): Record<string, CachedPath> {
	return readCache().discovered;
}
