/**
 * MCP Config Writer Module
 *
 * Writes Vreko MCP configuration to AI client config files.
 * Handles backup creation, merging with existing config, and various formats.
 *
 * @packageDocumentation
 */

import { execSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { evictCachedPath } from "./path-cache.js";
import type {
	AIClientConfig,
	AIClientFormat,
	MCPConfig,
	MCPServerConfig,
	RemoveResult,
	VrekoConfigOptions,
	WriteResult,
} from "./types.js";

// =============================================================================
// PATH RESOLUTION UTILITIES
// =============================================================================

/** Cached node path to avoid repeated lookups */
let cachedNodePath: string | null = null;

/**
 * Resolve the absolute path to the Node.js executable
 *
 * This is critical for MCP reliability - using just "node" depends on PATH
 * which varies between environments (terminal vs IDE vs system service).
 *
 * @returns Absolute path to node, or "node" as fallback
 */
export function resolveNodePath(): string {
	if (cachedNodePath) {
		return cachedNodePath;
	}

	try {
		// Try `which node` (Unix) or `where node` (Windows)
		const isWindows = process.platform === "win32";
		const command = isWindows ? "where node" : "which node";
		const result = execSync(command, { encoding: "utf-8", timeout: 5000 }).trim();

		// On Windows, `where` may return multiple paths - take the first
		const nodePath = result.split(/\r?\n/)[0].trim();

		if (nodePath && existsSync(nodePath)) {
			cachedNodePath = nodePath;
			return nodePath;
		}
	} catch {
		// Fallback: try common paths
		const commonPaths = [
			"/opt/homebrew/bin/node", // macOS ARM (Homebrew)
			"/usr/local/bin/node", // macOS Intel (Homebrew)
			"/usr/bin/node", // Linux
			"C:\\Program Files\\nodejs\\node.exe", // Windows
		];

		for (const path of commonPaths) {
			if (existsSync(path)) {
				cachedNodePath = path;
				return path;
			}
		}
	}

	// Final fallback - use "node" and hope PATH is set
	return "node";
}

/**
 * Resolve the absolute path to the Vreko CLI binary.
 *
 * Shell aliases (e.g., `vreko`) are NEVER usable as MCP server commands because
 * IDE and service processes spawn without a shell  -  aliases are invisible to them.
 * Always resolve to an absolute path or a verifiable PATH entry.
 *
 * @returns Absolute path to vreko binary, or "vreko" as fallback
 */
export function resolveVrekoBinaryPath(): string {
	try {
		const isWindows = process.platform === "win32";
		const command = isWindows ? "where vreko" : "which vreko";
		const result = execSync(command, { encoding: "utf-8", timeout: 5000 }).trim();
		const binaryPath = result.split(/\r?\n/)[0].trim();
		if (binaryPath && existsSync(binaryPath)) {
			return binaryPath;
		}
	} catch {
		// PATH resolution failed  -  fall through to well-known paths
	}

	// Well-known absolute paths for Homebrew and npm-global installs.
	// These are stable across shell sessions and IDE spawned processes.
	const commonPaths = [
		"/opt/homebrew/bin/vreko", // macOS ARM (Homebrew)
		"/usr/local/bin/vreko", // macOS Intel (Homebrew / nvm)
		"/usr/bin/vreko", // Linux system
	];

	for (const p of commonPaths) {
		if (existsSync(p)) {
			return p;
		}
	}

	// Final fallback  -  will fail in IDE environments without a corrected PATH,
	// but doctor/probe will catch this and report ENOENT with a clear fix message.
	return "vreko";
}

/**
 * Check if a command is executable (exists in PATH or is absolute path)
 *
 * @param command - Command to check
 * @returns True if command is likely executable
 */
export function isCommandExecutable(command: string): boolean {
	// If it's an absolute path, check if file exists
	if (command.startsWith("/") || command.match(/^[A-Z]:\\/i)) {
		return existsSync(command);
	}

	// For relative commands, try to find them
	try {
		const isWindows = process.platform === "win32";
		const cmd = isWindows ? `where ${command}` : `which ${command}`;
		execSync(cmd, { encoding: "utf-8", timeout: 5000 });
		return true;
	} catch {
		return false;
	}
}

// =============================================================================
// CONFIG GENERATION
// =============================================================================

/**
 * Clients that require remote HTTP transport (cannot use local stdio).
 * Currently unused  -  remote HTTP is now the default transport.
 * Retained for future use if a client requires local stdio override.
 */
const _REMOTE_ONLY_CLIENTS: Set<string> = new Set([
	// Currently none
]);

/**
 * Generate Vreko MCP server configuration
 *
 * @param options - Configuration options
 * @returns MCP server config for Vreko
 *
 * @example
 * ```ts
 * // RECOMMENDED: NPX mode for npm-installed CLI
 * // Best for users who installed via: npm install -g @vreko/cli
 * const npxConfig = getVrekoMCPConfig({
 *   useNpx: true,
 *   workspaceRoot: '/path/to/project'
 * });
 * // Generates: npx @vreko/cli mcp --stdio --workspace /path/to/project
 *
 * // Workspace ID auth (no API key in config)
 * const config = getVrekoMCPConfig({
 *   workspaceId: 'ws_a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6'
 * });
 *
 * // Legacy: API key auth (still supported)
 * const legacyConfig = getVrekoMCPConfig({ apiKey: 'sb_live_xxx' });
 *
 * // Local development mode
 * const devConfig = getVrekoMCPConfig({
 *   useLocalDev: true,
 *   localCliPath: '/path/to/apps/cli/dist/index.js',
 *   workspaceRoot: '/path/to/project'
 * });
 *
 * // Custom remote server
 * const customConfig = getVrekoMCPConfig({
 *   serverUrl: 'https://custom-mcp.example.com',
 *   workspaceId: 'ws_xxx'
 * });
 *
 * // Legacy stdio mode (using binary)
 * const stdioConfig = getVrekoMCPConfig({
 *   useBinary: true,
 *   apiKey: 'sb_live_xxx'
 * });
 *
 * // Claude Desktop (auto-uses npx since Claude Desktop requires stdio)
 * const claudeConfig = getVrekoMCPConfig({
 *   client: 'claude',
 *   workspaceRoot: '/path/to/project'
 * });
 * ```
 */
export function getVrekoMCPConfig(options: VrekoConfigOptions = {}): MCPServerConfig {
	const {
		apiKey,
		workspaceId,
		serverUrl,
		useBinary = false,
		customCommand,
		additionalEnv,
		workspaceRoot,
		useLocalDev = false,
		localCliPath,
		useDoppler = false,
		dopplerProject = "vreko-shared",
		dopplerConfig = "dev",
		useSse = false,
		useStreamableHttp = false,
		client,
	} = options;

	// NPX is only engaged when explicitly requested.
	// The default transport is remote HTTP (Fly.io remote intelligence orchestrator).
	const useNpx = options.useNpx === true;

	// Build environment variables  -  only relevant for stdio transports.
	// HTTP transport uses headers, not env vars.
	const env: Record<string, string> = { ...additionalEnv };
	if (apiKey) {
		env.VREKO_API_KEY = apiKey;
	}

	// Priority 1: Custom command
	if (customCommand) {
		return {
			command: customCommand,
			args: [],
			...(Object.keys(env).length > 0 && { env }),
		};
	}

	// Priority 1.5: Claude Desktop  -  stdio-only client, always use npx
	// Claude Desktop does not support HTTP transport; a URL config is silently ignored.
	// Guard fires when client is "claude" and no explicit transport override is set.
	if (
		client === "claude" &&
		!customCommand &&
		!useSse &&
		!useStreamableHttp &&
		!useDoppler &&
		!useNpx &&
		!localCliPath
	) {
		const tier = apiKey ? "pro" : "free";
		const args = ["--yes", "@vreko/cli", "mcp", "--stdio", "--tier", tier];
		if (workspaceRoot) {
			args.push("--workspace", workspaceRoot);
		}
		return { command: "npx", args };
	}

	// Priority 2: Explicit SSE/Streamable-HTTP transport
	// Uses /mcp endpoint (single endpoint for POST/GET/DELETE).
	// NOTE: env vars don't work for HTTP  -  use headers instead.
	if (useSse || useStreamableHttp) {
		const url = serverUrl || "https://mcp.vreko.dev/mcp";
		const headers: Record<string, string> = {};
		if (workspaceId) {
			headers["x-workspace-id"] = workspaceId;
		}
		if (apiKey) {
			headers["x-api-key"] = apiKey;
		}
		return {
			url,
			...(Object.keys(headers).length > 0 && { headers }),
		};
	}

	// Priority 3: Doppler mode  -  wraps with `doppler run` for env injection
	if (useDoppler && localCliPath) {
		const nodePath = resolveNodePath();
		const dopplerBase = ["run", "--project", dopplerProject, "--config", dopplerConfig, "--"];
		const tier = apiKey ? "pro" : "free";
		const dopplerArgs = [...dopplerBase, nodePath, localCliPath, "mcp", "--stdio", "--tier", tier];
		if (workspaceRoot) {
			dopplerArgs.push("--workspace", workspaceRoot);
		}
		return { command: "doppler", args: dopplerArgs };
	}

	// Priority 4: Explicit NPX mode (stdio, npm-installed CLI)
	if (useNpx) {
		const tier = apiKey ? "pro" : "free";
		const args = ["--yes", "@vreko/cli", "mcp", "--stdio", "--tier", tier];
		if (workspaceRoot) {
			args.push("--workspace", workspaceRoot);
		}
		return {
			command: "npx",
			args,
			...(Object.keys(env).length > 0 && { env }),
		};
	}

	// Priority 5: Local development mode  -  direct node execution
	// CRITICAL: resolves absolute node path to avoid PATH issues in IDE processes
	if (useLocalDev && localCliPath) {
		const tier = apiKey ? "pro" : "free";
		const args = [localCliPath, "mcp", "--stdio", "--tier", tier];
		if (workspaceRoot) {
			args.push("--workspace", workspaceRoot);
		}
		const nodePath = resolveNodePath();
		return {
			command: nodePath,
			args,
			...(Object.keys(env).length > 0 && { env }),
		};
	}

	// Priority 6: Binary mode (legacy stdio transport)
	// CRITICAL: resolves absolute binary path  -  relative "vreko" fails in IDE
	// processes that spawn without a shell (no PATH augmentation, no aliases).
	if (useBinary) {
		const tier = apiKey ? "pro" : "free";
		const args = ["mcp", "--stdio", "--tier", tier];
		if (workspaceRoot) {
			args.push("--workspace", workspaceRoot);
		}
		return {
			command: resolveVrekoBinaryPath(),
			args,
			...(Object.keys(env).length > 0 && { env }),
		};
	}

	// Default: remote HTTP (Fly.io remote intelligence orchestrator)
	// apiKey and workspaceId go in headers  -  secure, not logged in URL.
	// additionalEnv is not forwarded for HTTP transport.
	const url = serverUrl || "https://mcp.vreko.dev/mcp";
	const headers: Record<string, string> = {};
	if (workspaceId) {
		headers["x-workspace-id"] = workspaceId;
	}
	if (apiKey) {
		headers["x-api-key"] = apiKey;
	}
	return {
		url,
		...(Object.keys(headers).length > 0 && { headers }),
	};
}

// =============================================================================
// CONFIG WRITING
// =============================================================================

/**
 * Write Vreko MCP config to an AI client's config file
 *
 * @param client - The AI client to configure
 * @param mcpConfig - The MCP server configuration
 * @returns Result of the write operation
 *
 * @example
 * ```ts
 * const client = getClient('cursor');
 * const mcpConfig = getVrekoMCPConfig({ apiKey: 'sk_...' });
 *
 * const result = writeClientConfig(client, mcpConfig);
 * if (result.success) {
 *   // output:('Configured! Backup at:', result.backup);
 * } else {
 *   console.error('Failed:', result.error);
 * }
 * ```
 */
export function writeClientConfig(client: AIClientConfig, mcpConfig: MCPServerConfig): WriteResult {
	try {
		// Ensure directory exists
		const configDir = dirname(client.configPath);
		mkdirSync(configDir, { recursive: true });

		// Read existing config or start fresh
		let existingConfig: MCPConfig = { mcpServers: {} };
		let hasExistingConfig = false;

		if (existsSync(client.configPath)) {
			try {
				const content = readFileSync(client.configPath, "utf-8");
				existingConfig = JSON.parse(content) as MCPConfig;
				hasExistingConfig = Object.keys(existingConfig).length > 0;
			} catch {
				// Invalid JSON, will overwrite
			}
		}

		// Create backup if there's existing content
		let backup: string | undefined;
		if (hasExistingConfig) {
			backup = `${client.configPath}.backup.${Date.now()}`;
			writeFileSync(backup, JSON.stringify(existingConfig, null, 2));
		}

		// Merge configs based on format
		const newConfig = mergeConfig(existingConfig, mcpConfig, client.format);

		// Write updated config
		writeFileSync(client.configPath, JSON.stringify(newConfig, null, 2));

		return { success: true, backup };
	} catch (error) {
		return {
			success: false,
			error: error instanceof Error ? error.message : "Unknown error",
		};
	}
}

/**
 * Remove Vreko configuration from an AI client
 * §10.1: Removes namespaced entries (vreko-<client>)
 *
 * @param client - The AI client to remove config from
 * @returns Result of the removal operation
 */
export function removeVrekoConfig(client: AIClientConfig): RemoveResult {
	try {
		if (!existsSync(client.configPath)) {
			return { success: true }; // Nothing to remove
		}

		const content = readFileSync(client.configPath, "utf-8");
		const config = JSON.parse(content) as MCPConfig;
		// Remove based on format
		switch (client.format) {
			case "claude":
			case "cursor":
			case "windsurf":
			case "cline":
			case "roo-code":
			case "gemini":
			case "claude-code":
			case "qoder": {
				// Remove namespaced keys
				for (const key of Object.keys(config.mcpServers ?? {})) {
					if (isVrekoServerName(key, client.format)) {
						delete config.mcpServers[key];
					}
				}
				break;
			}

			case "vscode": {
				// VS Code uses "servers" not "mcpServers"
				const vscodeConfig = config as unknown as Record<string, unknown>;
				const servers = vscodeConfig.servers as Record<string, unknown> | undefined;
				for (const key of Object.keys(servers ?? {})) {
					if (servers && isVrekoServerName(key, client.format)) {
						delete servers[key];
					}
				}
				break;
			}

			case "zed": {
				// Zed uses "context_servers" not "mcpServers"
				const zedConfig = config as unknown as Record<string, unknown>;
				const contextServers = zedConfig.context_servers as Record<string, unknown> | undefined;
				for (const key of Object.keys(contextServers ?? {})) {
					if (contextServers && isVrekoServerName(key, client.format)) {
						delete contextServers[key];
					}
				}
				break;
			}

			case "continue": {
				// Continue uses different structure
				const experimental = (config as unknown as Record<string, unknown>).experimental as
					| Record<string, unknown>
					| undefined;
				if (experimental?.modelContextProtocolServers) {
					const servers = experimental.modelContextProtocolServers as Array<{ name: string }>;
					// Remove all vreko entries
					experimental.modelContextProtocolServers = servers.filter(
						(s) => !isVrekoServerName(s.name, "continue"),
					);
				}
				break;
			}
		}

		writeFileSync(client.configPath, JSON.stringify(config, null, 2));

		// Evict the path cache so the next detectAIClients re-probes all candidates
		evictCachedPath(client.name);

		return { success: true };
	} catch (error) {
		return {
			success: false,
			error: error instanceof Error ? error.message : "Unknown error",
		};
	}
}

// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

/**
 * §10.1: Generate namespaced server key for client
 * Vreko SHALL NEVER use just "vreko" - always "vreko-<client>"
 *
 * @param client - Client format (e.g., "claude", "cursor")
 * @returns Namespaced server key (e.g., "vreko-claude")
 */
export function getServerKey(client: AIClientFormat | undefined): string {
	if (!client) {
		return "vreko"; // Primary server key
	}
	return `vreko-${client}`;
}

function isVrekoServerName(name: string, client: AIClientFormat | undefined): boolean {
	const serverKey = getServerKey(client);
	return name === serverKey || name === "vreko" || name.startsWith("vreko-");
}

/**
 * Merge Vreko config into existing config based on format
 * §10.1: Uses namespaced server keys (vreko-<client>)
 */
function mergeConfig(
	existing: MCPConfig,
	vrekoConfig: MCPServerConfig,
	format: AIClientConfig["format"],
): MCPConfig | Record<string, unknown> {
	// §10.1: Use namespaced server key
	const serverKey = getServerKey(format);

	switch (format) {
		case "claude":
		case "cursor":
		case "cline":
		case "roo-code":
		case "gemini":
		case "claude-code":
			// Standard mcpServers format with namespaced key
			return {
				...existing,
				mcpServers: {
					...(existing.mcpServers || {}),
					[serverKey]: vrekoConfig,
				},
			};

		case "windsurf":
			// Windsurf uses standard format but supports disabled and alwaysAllow fields for UX
			return {
				...existing,
				mcpServers: {
					...(existing.mcpServers || {}),
					[serverKey]: {
						...vrekoConfig,
						disabled: false, // Explicitly enable
						alwaysAllow: [], // Empty by default, user can configure
					},
				},
			};

		case "qoder": {
			// Qoder requires an explicit `type` field for every MCP server entry.
			//
			// Type mapping:
			//   "stdio"  -  command-based (local daemon via IPC)
			//   "sse"    -  SSE transport for local dev servers (localhost/127.0.0.1)
			//   "http"   -  MCP Streamable HTTP for remote production servers
			//             (e.g. mcp.vreko.dev/mcp uses POST/GET/DELETE on one endpoint)
			let qoderType: "stdio" | "sse" | "http";
			if (vrekoConfig.url) {
				const isLocal =
					vrekoConfig.url.startsWith("http://localhost") || vrekoConfig.url.startsWith("http://127.0.0.1");
				qoderType = isLocal ? "sse" : "http";
			} else {
				qoderType = "stdio";
			}
			return {
				...existing,
				mcpServers: {
					...(existing.mcpServers || {}),
					[serverKey]: {
						type: qoderType,
						...vrekoConfig,
					},
				},
			};
		}

		case "vscode": {
			// VS Code uses "servers" not "mcpServers" and requires explicit type
			const vscodeConfig = existing as unknown as Record<string, unknown>;
			const servers = (vscodeConfig.servers || {}) as Record<string, unknown>;
			// Remove mcpServers if it exists (shouldn't be there for VS Code)
			const { mcpServers: _, ...rest } = vscodeConfig;
			return {
				...rest,
				servers: {
					...servers,
					[serverKey]: {
						type: "stdio", // Required by VS Code
						...vrekoConfig,
					},
				},
			};
		}

		case "zed": {
			// Zed uses "context_servers" not "mcpServers"
			const zedConfig = existing as unknown as Record<string, unknown>;
			const contextServers = (zedConfig.context_servers || {}) as Record<string, unknown>;
			// Remove mcpServers if it exists (shouldn't be there for Zed)
			const { mcpServers: _, ...rest } = zedConfig;
			return {
				...rest,
				context_servers: {
					...contextServers,
					[serverKey]: vrekoConfig,
				},
			};
		}

		case "continue": {
			// Continue uses experimental.modelContextProtocolServers array
			const continueConfig = existing as unknown as Record<string, unknown>;
			const experimental = (continueConfig.experimental || {}) as Record<string, unknown>;
			const servers = (experimental.modelContextProtocolServers || []) as Array<Record<string, unknown>>;

			// Remove existing vreko entries if present
			const filteredServers = servers.filter((s) => {
				const name = s.name as string;
				return !name?.startsWith("vreko");
			});

			// Add new vreko config with namespaced name
			filteredServers.push({
				name: serverKey,
				...vrekoConfig,
			});

			return {
				...continueConfig,
				experimental: {
					...experimental,
					modelContextProtocolServers: filteredServers,
				},
			};
		}

		case "aider":
			// Aider uses YAML - handled separately (this shouldn't be called)
			// For now, return existing config unchanged
			return existing;

		default:
			// Fallback to standard format with namespaced key
			return {
				...existing,
				mcpServers: {
					...(existing.mcpServers || {}),
					[serverKey]: vrekoConfig,
				},
			};
	}
}

/**
 * Patch VREKO_API_KEY in an existing Vreko MCP server entry.
 *
 * Reads the client config, finds any vreko-* server entry, updates (or
 * adds) the env.VREKO_API_KEY value, and writes the file back. This is
 * called after `vreko login` to upgrade any pre-existing zero-config configs
 * with the newly provisioned sk_live_* key.
 *
 * @param client - The AI client whose config should be patched
 * @param apiKey - The sk_live_* key to inject
 * @returns Whether the patch succeeded
 */
export function patchApiKeyInClientConfig(client: AIClientConfig, apiKey: string): boolean {
	try {
		if (!existsSync(client.configPath)) {
			return false;
		}

		const raw = readFileSync(client.configPath, "utf-8");
		const config = JSON.parse(raw) as Record<string, unknown>;
		let patched = false;

		const patchEntry = (entry: unknown): boolean => {
			if (typeof entry !== "object" || entry === null) {
				return false;
			}
			const e = entry as Record<string, unknown>;
			// HTTP transport (has URL): inject key into headers so it reaches the remote server
			if (e.url && typeof e.url === "string") {
				if (!e.headers || typeof e.headers !== "object") {
					e.headers = {};
				}
				(e.headers as Record<string, string>)["x-api-key"] = apiKey;
				// Remove stale placeholder Authorization header if present
				const headers = e.headers as Record<string, string>;
				if (headers.Authorization?.includes("<your-token>")) {
					delete headers.Authorization;
				}
				return true;
			}
			// Stdio transport: inject key into env
			if (!e.env || typeof e.env !== "object") {
				e.env = {};
			}
			(e.env as Record<string, string>).VREKO_API_KEY = apiKey;
			return true;
		};

		switch (client.format) {
			case "claude":
			case "cursor":
			case "windsurf":
			case "cline":
			case "roo-code":
			case "gemini":
			case "claude-code": {
				const servers = (config.mcpServers || {}) as Record<string, unknown>;
				for (const [name, entry] of Object.entries(servers)) {
					if (isVrekoServerName(name, client.format)) {
						patched = patchEntry(entry) || patched;
					}
				}
				break;
			}
			case "qoder": {
				// Patch all vreko entries
				const servers = (config.mcpServers || {}) as Record<string, unknown>;
				for (const [name, entry] of Object.entries(servers)) {
					if (isVrekoServerName(name, client.format)) {
						patched = patchEntry(entry) || patched;
					}
				}
				break;
			}
			case "vscode": {
				const servers = (config.servers || {}) as Record<string, unknown>;
				for (const [name, entry] of Object.entries(servers)) {
					if (isVrekoServerName(name, client.format)) {
						patched = patchEntry(entry) || patched;
					}
				}
				break;
			}
			case "zed": {
				const servers = (config.context_servers || {}) as Record<string, unknown>;
				for (const [name, entry] of Object.entries(servers)) {
					if (isVrekoServerName(name, client.format)) {
						patched = patchEntry(entry) || patched;
					}
				}
				break;
			}
			case "continue": {
				const exp = (config.experimental || {}) as Record<string, unknown>;
				const list = (exp.modelContextProtocolServers || []) as Array<Record<string, unknown>>;
				for (const item of list) {
					if (typeof item.name === "string" && isVrekoServerName(item.name, "continue")) {
						patched = patchEntry(item) || patched;
					}
				}
				break;
			}
		}

		if (patched) {
			writeFileSync(client.configPath, JSON.stringify(config, null, 2));
		}
		return patched;
	} catch {
		return false;
	}
}

/**
 * Validate that a config was written correctly
 * §10.1: Checks for namespaced server keys (vreko-<client>)
 *
 * @param client - Client to validate
 * @returns True if Vreko is properly configured
 */
export function validateConfig(client: AIClientConfig): boolean {
	try {
		const content = readFileSync(client.configPath, "utf-8");
		const config = JSON.parse(content) as MCPConfig;
		switch (client.format) {
			case "claude":
			case "cursor":
			case "windsurf":
			case "cline":
			case "roo-code":
			case "gemini":
			case "claude-code":
			case "qoder": {
				// Check namespaced keys
				const servers = config.mcpServers ?? {};
				return Object.entries(servers).some(
					([name, serverConfig]) =>
						isVrekoServerName(name, client.format) &&
						typeof serverConfig === "object" &&
						serverConfig !== null &&
						Boolean(
							(serverConfig as { command?: string; url?: string }).command ||
								(serverConfig as { command?: string; url?: string }).url,
						),
				);
			}

			case "vscode": {
				// VS Code uses "servers" not "mcpServers"
				const vscodeConfig = config as unknown as Record<string, unknown>;
				const servers = vscodeConfig.servers as Record<string, unknown> | undefined;
				return Boolean(
					Object.entries(servers ?? {}).some(
						([name, serverConfig]) =>
							isVrekoServerName(name, client.format) &&
							typeof serverConfig === "object" &&
							serverConfig !== null &&
							Boolean(
								(serverConfig as { command?: string; url?: string }).command ||
									(serverConfig as { command?: string; url?: string }).url,
							),
					),
				);
			}

			case "zed": {
				// Zed uses "context_servers" not "mcpServers"
				const zedConfig = config as unknown as Record<string, unknown>;
				const contextServers = zedConfig.context_servers as Record<string, unknown> | undefined;
				return Boolean(
					Object.entries(contextServers ?? {}).some(
						([name, serverConfig]) =>
							isVrekoServerName(name, client.format) &&
							typeof serverConfig === "object" &&
							serverConfig !== null &&
							Boolean(
								(serverConfig as { command?: string; url?: string }).command ||
									(serverConfig as { command?: string; url?: string }).url,
							),
					),
				);
			}

			case "continue": {
				const expCfg = (config as unknown as Record<string, unknown>).experimental as
					| Record<string, unknown>
					| undefined;
				const srvs = expCfg?.modelContextProtocolServers as
					| Array<{ name: string; command?: string; url?: string }>
					| undefined;
				// Check for any vreko entry
				return Boolean(srvs?.some((s) => isVrekoServerName(s.name, "continue") && (s.command || s.url)));
			}

			case "aider":
				// YAML validation would need a YAML parser
				return false;

			default:
				return false;
		}
	} catch {
		return false;
	}
}
