/**
 * AI Client Detection Module
 *
 * Detects installed AI assistants (Claude Desktop, Cursor, Windsurf, Continue)
 * and checks their MCP configuration status.
 *
 * @packageDocumentation
 */

import { existsSync, readFileSync } from "node:fs";
import { homedir, platform } from "node:os";
import { join } from "node:path";
import { getCachedPath, setCachedPath } from "./path-cache.js";
import type { AIClientConfig, AIClientFormat, DetectionResult, MCPConfig } from "./types.js";

// =============================================================================
// CLIENT PATH CONFIGURATION
// =============================================================================

/**
 * Platform-specific config path resolvers for each AI client
 * Note: User preference is project-level configs where supported
 */
const CLIENT_CONFIGS: Record<string, (home: string, cwd?: string) => string[]> = {
	claude: (home) => {
		switch (platform()) {
			case "darwin":
				return [join(home, "Library/Application Support/Claude/claude_desktop_config.json")];
			case "win32":
				return [join(process.env.APPDATA || "", "Claude/claude_desktop_config.json")];
			default:
				return [join(home, ".config/Claude/claude_desktop_config.json")];
		}
	},
	// Project-level first (user preference), then global fallback
	cursor: (_home, cwd) => [...(cwd ? [join(cwd, ".cursor/mcp.json")] : []), join(_home, ".cursor/mcp.json")],
	// Windsurf only has a global config  -  no project-level support (confirmed by Windsurf docs, June 2025)
	windsurf: (home) => [join(home, ".codeium/windsurf/mcp_config.json")],
	// Continue: global config.json or config.yaml; project-level .continue/mcpServers/mcp.json
	continue: (home, cwd) => [
		...(cwd ? [join(cwd, ".continue/mcpServers/mcp.json")] : []),
		join(home, ".continue/config.json"),
		join(home, ".continue/config.yaml"),
	],
	// New clients
	vscode: (_home, cwd) => [...(cwd ? [join(cwd, ".vscode/mcp.json")] : [])],
	// Zed: global ~/.config/zed/settings.json, plus project-level .zed/settings.json
	zed: (home, cwd) => [...(cwd ? [join(cwd, ".zed/settings.json")] : []), join(home, ".config/zed/settings.json")],
	// Cline / Roo Code store their actual settings in VS Code extension globalStorage,
	// but `vreko tools configure --cline/--roo-code` writes to these paths as a side-channel.
	// Detection via these paths is best-effort; users may need `vreko mcp link --client cline` instead.
	cline: (home) => [join(home, ".cline/mcp.json")],
	gemini: (home) => [join(home, ".gemini/settings.json")],
	aider: (home) => [join(home, ".aider/mcp.yaml")],
	"roo-code": (home) => [join(home, ".roo-code/mcp.json")],
	// Qoder (VS Code fork) - supports both project-level and global configs
	qoder: (home, cwd) => {
		const workspaceConfig = cwd ? [join(cwd, ".qoder-mcp-config.json")] : [];
		const globalConfigs: string[] = (() => {
			switch (platform()) {
				case "darwin":
					// Primary location (SharedClientCache/mcp.json) is where Qoder actually writes
					// Legacy path (extension/local/mcp.json) kept for backwards compatibility
					return [
						join(home, "Library/Application Support/Qoder/SharedClientCache/mcp.json"),
						join(home, "Library/Application Support/Qoder/SharedClientCache/extension/local/mcp.json"),
					];
				case "win32":
					return [join(process.env.APPDATA || "", "Qoder/mcp.json")];
				default:
					return [join(home, ".config/Qoder/mcp.json")];
			}
		})();
		return [...workspaceConfig, ...globalConfigs];
	},
	// Claude Code CLI  -  project-scoped .mcp.json at workspace root
	"claude-code": (_home, cwd) => [...(cwd ? [join(cwd, ".mcp.json")] : [join(process.cwd(), ".mcp.json")])],
};

/**
 * Display names for AI clients
 */
const CLIENT_DISPLAY_NAMES: Record<string, string> = {
	claude: "Claude Desktop",
	cursor: "Cursor",
	windsurf: "Windsurf",
	continue: "Continue",
	vscode: "VS Code",
	zed: "Zed",
	cline: "Cline",
	gemini: "Gemini/Antigravity",
	aider: "Aider",
	"roo-code": "Roo Code",
	qoder: "Qoder",
	"claude-code": "Claude Code",
};

/**
 * Clients whose MCP config format Vreko cannot write correctly.
 * These clients are detected (so explicit `vreko tools configure --<client>` still works)
 * but are excluded from the `needsSetup` list returned by detectAIClients().
 * Zed: uses extension-based context_servers format that differs from mcpServers JSON.
 * Continue: uses experimental.modelContextProtocolServers array; no confirmed working transport.
 */
const UNSUPPORTED_DEFAULT_INIT_CLIENTS: ReadonlySet<string> = new Set(["zed", "continue"]);

function hasVrekoServerName(name: string, format?: AIClientFormat): boolean {
	if (name === "vreko") {
		return true;
	}
	if (format && name === `vreko-${format}`) {
		return true;
	}
	return name.startsWith("vreko-");
}

// =============================================================================
// DETECTION FUNCTIONS
// =============================================================================

/**
 * Detect all AI clients and their configuration status
 *
 * @param options - Detection options
 * @param options.cwd - Current working directory for project-level configs
 * @returns Detection result with all clients, detected clients, and clients needing setup
 *
 * @example
 * ```ts
 * const result = detectAIClients();
 * // output:(`Found ${result.detected.length} AI assistants`);
 *
 * for (const client of result.needsSetup) {
 *   // output:(`${client.displayName} needs Vreko configuration`);
 * }
 * ```
 */
export function detectAIClients(options: { cwd?: string } = {}): DetectionResult {
	const home = homedir();
	const cwd = options.cwd || process.cwd();
	const clients: AIClientConfig[] = [];
	const seenPaths = new Set<string>();

	for (const [name, getPaths] of Object.entries(CLIENT_CONFIGS)) {
		const candidates = getPaths(home, cwd);

		// Check the path cache first  -  avoids re-probing all candidates on every run.
		// The cache entry is only valid if the file still exists (getCachedPath verifies this).
		const cachedPath = getCachedPath(name);
		const paths =
			cachedPath && candidates.includes(cachedPath)
				? [cachedPath, ...candidates.filter((p) => p !== cachedPath)]
				: candidates;

		for (const configPath of paths) {
			// Avoid duplicate entries for same path
			if (seenPaths.has(configPath)) {
				continue;
			}
			seenPaths.add(configPath);

			const exists = existsSync(configPath);
			let hasVreko = false;

			if (exists) {
				// Cache this path so future runs skip the other candidates
				setCachedPath(name, configPath);
				try {
					const content = readFileSync(configPath, "utf-8");
					// Handle YAML for aider
					if (configPath.endsWith(".yaml") || configPath.endsWith(".yml")) {
						hasVreko = content.includes("vreko");
					} else {
						const parsed = JSON.parse(content) as unknown;
						hasVreko = checkForVreko(parsed, name as AIClientFormat);
					}
				} catch {
					// Invalid JSON/YAML or read error - treat as no vreko
				}
			}

			clients.push({
				name,
				displayName: CLIENT_DISPLAY_NAMES[name] || name,
				configPath,
				exists,
				hasVreko,
				format: name as AIClientFormat,
			});
		}
	}

	const detected = clients.filter((c) => c.exists);
	// Exclude clients whose config format is not supported for automatic init.
	// They remain in `detected` so explicit tool commands can still target them.
	const needsSetup = detected.filter((c) => !c.hasVreko && !UNSUPPORTED_DEFAULT_INIT_CLIENTS.has(c.name));

	return { clients, detected, needsSetup };
}

/**
 * Check if a specific AI client is installed
 *
 * @param clientName - Name of the client to check (claude, cursor, windsurf, continue)
 * @returns The client config if found, undefined otherwise
 */
export function getClient(clientName: string): AIClientConfig | undefined {
	const result = detectAIClients();
	return result.clients.find((c) => c.name === clientName && c.exists);
}

/**
 * Get all clients that have Vreko configured
 *
 * @returns Array of configured clients
 */
export function getConfiguredClients(): AIClientConfig[] {
	const result = detectAIClients();
	return result.detected.filter((c) => c.hasVreko);
}

// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

/**
 * Check if Vreko is configured in a config object
 */
function checkForVreko(config: unknown, format: AIClientFormat): boolean {
	if (!config || typeof config !== "object") {
		return false;
	}

	const configObj = config as Record<string, unknown>;

	switch (format) {
		case "claude":
		case "cursor":
		case "windsurf":
		case "cline":
		case "roo-code":
		case "claude-code":
			// These use mcpServers.vreko format
			if (
				"mcpServers" in configObj &&
				typeof configObj.mcpServers === "object" &&
				configObj.mcpServers !== null
			) {
				const servers = configObj.mcpServers as Record<string, unknown>;
				// Check for namespaced key
				return Object.keys(servers).some((serverName) => hasVrekoServerName(serverName, format));
			}
			return false;

		case "qoder":
			// Qoder uses mcpServers format but may have multiple vreko entries
			// (e.g. vreko-local and vreko-remote) from vreko mcp link
			if (
				"mcpServers" in configObj &&
				typeof configObj.mcpServers === "object" &&
				configObj.mcpServers !== null
			) {
				const servers = configObj.mcpServers as Record<string, unknown>;
				// Check for any vreko-prefixed key
				return Object.keys(servers).some((k) => hasVrekoServerName(k));
			}
			return false;

		case "vscode":
			// VS Code uses "servers" not "mcpServers"
			if ("servers" in configObj && typeof configObj.servers === "object" && configObj.servers !== null) {
				const servers = configObj.servers as Record<string, unknown>;
				// Check for namespaced key
				return Object.keys(servers).some((serverName) => hasVrekoServerName(serverName, "vscode"));
			}
			return false;

		case "gemini":
		case "zed":
			// Zed uses "context_servers" not "mcpServers"
			if (
				"context_servers" in configObj &&
				typeof configObj.context_servers === "object" &&
				configObj.context_servers !== null
			) {
				const servers = configObj.context_servers as Record<string, unknown>;
				// Check for namespaced key
				return Object.keys(servers).some((serverName) => hasVrekoServerName(serverName, "zed"));
			}
			// Fallback: also check mcpServers for gemini
			if (
				"mcpServers" in configObj &&
				typeof configObj.mcpServers === "object" &&
				configObj.mcpServers !== null
			) {
				const servers = configObj.mcpServers as Record<string, unknown>;
				return Object.keys(servers).some((serverName) => hasVrekoServerName(serverName, format));
			}
			return false;

		case "continue":
			// Continue uses a different structure - check for experimental.modelContextProtocolServers
			if (
				"experimental" in configObj &&
				typeof configObj.experimental === "object" &&
				configObj.experimental !== null
			) {
				const experimental = configObj.experimental as Record<string, unknown>;
				if (
					"modelContextProtocolServers" in experimental &&
					Array.isArray(experimental.modelContextProtocolServers)
				) {
					return experimental.modelContextProtocolServers.some(
						(server: unknown) =>
							typeof server === "object" &&
							server !== null &&
							typeof (server as Record<string, unknown>).name === "string" &&
							hasVrekoServerName((server as Record<string, unknown>).name as string),
					);
				}
			}
			return false;

		case "aider":
			// Aider uses YAML - handled separately in detectAIClients
			return false;

		default:
			return false;
	}
}

/**
 * Get the expected config path for a client on the current platform
 *
 * @param clientName - Name of the client
 * @param cwd - Current working directory (for project-level configs)
 * @returns The config path or undefined if unknown client
 */
export function getClientConfigPath(clientName: string, cwd?: string): string | undefined {
	const getPaths = CLIENT_CONFIGS[clientName];
	if (!getPaths) {
		return undefined;
	}

	const paths = getPaths(homedir(), cwd);
	return paths[0];
}

/**
 * Read and parse a client's MCP config file
 *
 * @param client - The client to read config for
 * @returns Parsed config or undefined if not found/invalid
 */
export function readClientConfig(client: AIClientConfig): MCPConfig | undefined {
	try {
		const content = readFileSync(client.configPath, "utf-8");
		return JSON.parse(content) as MCPConfig;
	} catch {
		return undefined;
	}
}

/**
 * Detect workspace-specific MCP configurations
 * Checks for project-level configs that take precedence over global ones
 *
 * @param workspaceRoot - Workspace root directory (defaults to cwd)
 * @returns Config info if found, null otherwise
 *
 * @example
 * ```ts
 * const wsConfig = detectWorkspaceConfig();
 * if (wsConfig) {
 *   // output:(`Found workspace config: ${wsConfig.path}`);
 *   // Skip adding global config to prevent conflicts
 * }
 * ```
 */
export function detectWorkspaceConfig(
	workspaceRoot?: string,
): { path: string; type: "qoder" | "vscode" | "cursor" | "windsurf" | "claude-code" } | null {
	const root = workspaceRoot || process.cwd();

	// Check Claude Code project config (.mcp.json at workspace root)
	const claudeCodeConfig = join(root, ".mcp.json");
	if (existsSync(claudeCodeConfig)) {
		try {
			const content = readFileSync(claudeCodeConfig, "utf-8");
			if (content.includes("vreko")) {
				return { path: claudeCodeConfig, type: "claude-code" };
			}
		} catch {
			// Invalid JSON or read error
		}
	}

	// Check Qoder workspace config (.qoder-mcp-config.json)
	const qoderConfig = join(root, ".qoder-mcp-config.json");
	if (existsSync(qoderConfig)) {
		try {
			const content = readFileSync(qoderConfig, "utf-8");
			if (content.includes("vreko")) {
				return { path: qoderConfig, type: "qoder" };
			}
		} catch {
			// Invalid JSON or read error
		}
	}

	// Check Cursor project config (.cursor/mcp.json)
	const cursorConfig = join(root, ".cursor", "mcp.json");
	if (existsSync(cursorConfig)) {
		try {
			const content = readFileSync(cursorConfig, "utf-8");
			if (content.includes("vreko")) {
				return { path: cursorConfig, type: "cursor" };
			}
		} catch {
			// Invalid JSON or read error
		}
	}

	// Check VS Code project config (.vscode/mcp.json)
	const vscodeConfig = join(root, ".vscode", "mcp.json");
	if (existsSync(vscodeConfig)) {
		try {
			const content = readFileSync(vscodeConfig, "utf-8");
			if (content.includes("vreko")) {
				return { path: vscodeConfig, type: "vscode" };
			}
		} catch {
			// Invalid JSON or read error
		}
	}

	// Check Windsurf project config (.windsurf/mcp.json)
	const windsurfConfig = join(root, ".windsurf", "mcp.json");
	if (existsSync(windsurfConfig)) {
		try {
			const content = readFileSync(windsurfConfig, "utf-8");
			if (content.includes("vreko")) {
				return { path: windsurfConfig, type: "windsurf" };
			}
		} catch {
			// Invalid JSON or read error
		}
	}

	return null;
}
