/**
 * MCP Process Detection Module
 *
 * Detects running MCP stdio processes spawned by AI clients.
 * This helps verify that MCP configuration is not just present,
 * but actually functional with processes running.
 *
 * @packageDocumentation
 */

import { exec } from "node:child_process";
import { promisify } from "node:util";

const execAsync = promisify(exec);

/**
 * Running MCP process information
 */
export interface MCPProcess {
	/** Process ID */
	pid: number;
	/** Command being executed */
	command: string;
	/** MCP server name (e.g., "vreko", "context7") */
	serverName: string;
	/** Whether this is a Vreko MCP process */
	isVreko: boolean;
}

/**
 * MCP process health status
 */
export interface MCPProcessHealth {
	/** All detected MCP stdio processes */
	allProcesses: MCPProcess[];
	/** Vreko-specific processes */
	vrekoProcesses: MCPProcess[];
	/** Whether any Vreko MCP process is running */
	vrekoRunning: boolean;
	/** Total count of all MCP processes */
	totalCount: number;
	/** Timestamp of check */
	checkedAt: Date;
}

/**
 * Detect running MCP stdio processes
 *
 * Uses `ps` command to find processes matching MCP stdio patterns:
 * - node ... mcp --stdio
 * - vreko mcp --stdio
 * - uvx mcp-server-*
 * - npx ... mcp ...
 *
 * @returns Health status of MCP processes
 *
 * @example
 * ```ts
 * const health = await detectMCPProcesses();
 * if (health.vrekoRunning) {
 *   // output:(`✓ Vreko MCP running (${health.vrekoProcesses.length} processes)`);
 * } else {
 *   // output:('⚠ Vreko MCP not running');
 * }
 * ```
 */
export async function detectMCPProcesses(): Promise<MCPProcessHealth> {
	try {
		// Use ps to find MCP-related processes
		// grep for common patterns: stdio, mcp, server names
		const { stdout } = await execAsync(
			'ps aux | grep -E "(mcp.*--stdio|--stdio.*mcp|uvx.*mcp-server|npx.*mcp|node.*mcp)" | grep -v grep',
			{
				timeout: 5000, // 5s timeout
			},
		);

		const processes = parseProcessOutput(stdout);
		const vrekoProcesses = processes.filter((p) => p.isVreko);

		return {
			allProcesses: processes,
			vrekoProcesses,
			vrekoRunning: vrekoProcesses.length > 0,
			totalCount: processes.length,
			checkedAt: new Date(),
		};
	} catch {
		// ps command failed or no processes found (grep returns exit code 1)
		// Return empty result rather than throwing
		return {
			allProcesses: [],
			vrekoProcesses: [],
			vrekoRunning: false,
			totalCount: 0,
			checkedAt: new Date(),
		};
	}
}

/**
 * Parse ps output into MCPProcess objects
 */
function parseProcessOutput(output: string): MCPProcess[] {
	const lines = output
		.trim()
		.split("\n")
		.filter((line) => line.trim());

	const processes: MCPProcess[] = [];

	for (const line of lines) {
		// ps aux output format: USER PID %CPU %MEM VSZ RSS TTY STAT START TIME COMMAND
		// We need PID and COMMAND
		const match = line.match(/^(\S+)\s+(\d+)\s+.*?\s+(.+)$/);
		if (!match) {
			continue;
		}

		const [, , pidStr, command] = match;
		const pid = Number.parseInt(pidStr, 10);

		if (Number.isNaN(pid)) {
			continue;
		}

		// Determine server name from command
		const serverName = extractServerName(command);
		const isVreko = command.toLowerCase().includes("vreko");

		processes.push({
			pid,
			command: command.trim(),
			serverName,
			isVreko,
		});
	}

	return processes;
}

/**
 * Extract MCP server name from command string
 */
function extractServerName(command: string): string {
	// Try to extract server name from common patterns
	const patterns = [
		// vreko mcp --stdio
		/vreko[/\s]/i,
		// mcp-server-fetch
		/mcp-server-(\w+)/,
		// @modelcontextprotocol/server-sequential-thinking
		/server-(\w+)/,
		// context7-mcp
		/(\w+)-mcp/,
		// fly mcp server
		/fly.*mcp/i,
		// supabase-mcp
		/supabase-mcp/i,
	];

	for (const pattern of patterns) {
		const match = command.match(pattern);
		if (match) {
			// Return first capture group or full match
			return match[1] || match[0];
		}
	}

	// Fallback: just say "mcp"
	return "mcp";
}

/**
 * Quick check if Vreko MCP is running
 *
 * Lightweight version that just returns boolean.
 *
 * @returns true if Vreko MCP process detected
 */
export async function isVrekoMCPRunning(): Promise<boolean> {
	const health = await detectMCPProcesses();
	return health.vrekoRunning;
}
