/**
 * MCP Config Repair Module
 *
 * Automatically repairs broken or incomplete MCP configurations.
 * Provides autonomous recovery for common failure scenarios.
 *
 * @packageDocumentation
 */

import { existsSync } from "node:fs";
import { resolve } from "node:path";

import type { AIClientConfig } from "./types.js";
import { type ValidationResult, validateClientConfig } from "./validate.js";
import { getVrekoMCPConfig, resolveNodePath, writeClientConfig } from "./write.js";

// =============================================================================
// TYPES
// =============================================================================

export interface RepairResult {
	/** Whether repair was successful */
	success: boolean;
	/** Issues that were fixed */
	fixed: string[];
	/** Issues that remain unfixed */
	remaining: string[];
	/** Error message if repair failed */
	error?: string;
}

export interface RepairOptions {
	/** API key for Pro features */
	apiKey?: string;
	/** Workspace ID for tier resolution */
	workspaceId?: string;
	/** Workspace root path (auto-detected if not provided) */
	workspaceRoot?: string;
	/** Whether to force complete reconfiguration */
	force?: boolean;
}

// =============================================================================
// REPAIR FUNCTIONS
// =============================================================================

/**
 * Automatically repair a client's MCP configuration
 *
 * @param client - The client to repair
 * @param options - Repair options
 * @returns Repair result with fixes applied
 *
 * @example
 * ```ts
 * const client = getClient('qoder');
 * const result = await repairClientConfig(client, {
 *   workspaceRoot: process.cwd()
 * });
 *
 * if (result.success) {
 *   // output:('Fixed:', result.fixed);
 * } else {
 *   console.error('Remaining issues:', result.remaining);
 * }
 * ```
 */
export function repairClientConfig(client: AIClientConfig, options: RepairOptions = {}): RepairResult {
	const fixed: string[] = [];
	const remaining: string[] = [];

	// Validate current config
	const validation = validateClientConfig(client);

	// If force, just reconfigure completely
	if (options.force) {
		return performFullReconfiguration(client, options);
	}

	// If no issues, no repair needed
	if (validation.valid && validation.issues.length === 0) {
		return { success: true, fixed: [], remaining: [] };
	}

	// Try to fix each issue
	for (const issue of validation.issues) {
		const fixResult = attemptFix(client, issue, validation, options);
		if (fixResult.success) {
			fixed.push(issue.message);
		} else {
			remaining.push(issue.message);
		}
	}

	// If critical issues remain, do full reconfiguration
	const hasCriticalErrors = remaining.some((msg) =>
		validation.issues.find((i) => i.message === msg && i.severity === "error"),
	);

	if (hasCriticalErrors) {
		return performFullReconfiguration(client, options);
	}

	return {
		success: remaining.length === 0,
		fixed,
		remaining,
	};
}

/**
 * Auto-inject workspace path into MCP config
 *
 * This is the most common repair needed - automatically detecting
 * and injecting the correct workspace path when missing.
 *
 * @param client - The client to update
 * @param workspaceRoot - Workspace path (auto-detected if not provided)
 * @returns Result of the injection
 */
export function injectWorkspacePath(client: AIClientConfig, workspaceRoot?: string): RepairResult {
	const fixed: string[] = [];
	const remaining: string[] = [];

	// Detect workspace if not provided
	const detectedWorkspace = workspaceRoot || detectWorkspaceRoot(process.cwd());

	if (!detectedWorkspace) {
		return {
			success: false,
			fixed,
			remaining: ["Could not auto-detect workspace root"],
			error: "No workspace markers found (.git, package.json, .vreko)",
		};
	}

	// Validate detected workspace
	if (!existsSync(detectedWorkspace)) {
		return {
			success: false,
			fixed,
			remaining: [`Workspace path does not exist: ${detectedWorkspace}`],
			error: "Invalid workspace path",
		};
	}

	// Get current config
	const validation = validateClientConfig(client);
	if (!validation.config) {
		return {
			success: false,
			fixed,
			remaining: ["No existing Vreko config found"],
			error: "Must run initial configuration first",
		};
	}

	// Check if using stdio transport
	if (!validation.config.command) {
		// Using HTTP transport, no workspace injection needed
		return {
			success: true,
			fixed: ["Config uses HTTP transport - no workspace path needed"],
			remaining: [],
		};
	}

	// Check if workspace already set
	const hasWorkspace = validation.config.args?.includes("--workspace");
	if (hasWorkspace) {
		fixed.push("Workspace path already configured");
		return { success: true, fixed, remaining };
	}

	// Inject workspace by full reconfiguration
	const result = performFullReconfiguration(client, {
		workspaceRoot: detectedWorkspace,
	});

	if (result.success) {
		fixed.push(`Injected workspace path: ${detectedWorkspace}`);
	}

	return { success: result.success, fixed, remaining };
}

// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

/**
 * Attempt to fix a specific issue
 */
function attemptFix(
	client: AIClientConfig,
	issue: ValidationResult["issues"][0],
	_validation: ValidationResult,
	options: RepairOptions,
): { success: boolean } {
	switch (issue.code) {
		case "CONFIG_NOT_FOUND":
		case "CONFIG_PARSE_ERROR":
		case "VREKO_NOT_CONFIGURED":
		case "MISSING_COMMAND_OR_URL":
		case "MISSING_ARGS":
		case "MISSING_MCP_ARG":
		case "MISSING_STDIO_ARG":
		case "DEPRECATED_SHIM_COMMAND":
		case "INVALID_URL":
			// These require full reconfiguration
			return performFullReconfiguration(client, options);

		case "COMMAND_NOT_EXECUTABLE": {
			// Auto-fix by resolving correct node path
			// This is the most common issue in IDE environments
			return performFullReconfiguration(client, options);
		}

		case "CLI_PATH_NOT_FOUND": {
			// Try to find CLI path automatically
			const cliPath = findCliPath();
			if (cliPath) {
				return performFullReconfiguration(client, options);
			}
			return { success: false };
		}

		case "MISSING_WORKSPACE_ARG": {
			// Try to inject workspace
			const workspace = options.workspaceRoot || detectWorkspaceRoot(process.cwd());
			if (workspace) {
				return performFullReconfiguration(client, { ...options, workspaceRoot: workspace });
			}
			return { success: false };
		}

		case "WORKSPACE_NOT_FOUND": {
			// Try to detect correct workspace
			const detected = detectWorkspaceRoot(process.cwd());
			if (detected) {
				return performFullReconfiguration(client, { ...options, workspaceRoot: detected });
			}
			return { success: false };
		}

		case "WORKSPACE_NO_MARKERS":
			// Warn but don't fail - workspace might be valid
			return { success: true };

		case "NO_AUTH":
			// Info only, not an error
			return { success: true };

		default:
			return { success: false };
	}
}

/**
 * Perform full reconfiguration
 * Auto-fixes node path issues by using resolveNodePath()
 */
function performFullReconfiguration(client: AIClientConfig, options: RepairOptions): RepairResult {
	try {
		// Detect workspace if not provided
		const workspaceRoot = options.workspaceRoot || detectWorkspaceRoot(process.cwd());
		const cliPath = findCliPath();

		// Determine config mode based on available paths
		// biome-ignore lint/suspicious/noImplicitAnyLet: type inferred from getVrekoMCPConfig return type
		let mcpConfig;

		if (cliPath && workspaceRoot) {
			// Local dev mode with proper node path resolution
			mcpConfig = getVrekoMCPConfig({
				apiKey: options.apiKey,
				workspaceId: options.workspaceId,
				workspaceRoot,
				useLocalDev: true,
				localCliPath: cliPath,
				client: client.format, // Pass client format for transport selection
			});

			// Log the node path being used for debugging
			const _nodePath = resolveNodePath();
		} else {
			// Fallback mode - pass client format so stdio-only clients (like Claude Desktop) use npx
			mcpConfig = getVrekoMCPConfig({
				apiKey: options.apiKey,
				workspaceId: options.workspaceId,
				useLocalDev: false,
				client: client.format, // Pass client format for transport selection
			});
		}

		// Write config
		const writeResult = writeClientConfig(client, mcpConfig);

		if (writeResult.success) {
			return {
				success: true,
				fixed: ["Full reconfiguration completed (node path resolved)"],
				remaining: [],
			};
		}

		return {
			success: false,
			fixed: [],
			remaining: ["Write failed"],
			error: writeResult.error,
		};
	} catch (error) {
		return {
			success: false,
			fixed: [],
			remaining: ["Reconfiguration failed"],
			error: error instanceof Error ? error.message : "Unknown error",
		};
	}
}

/**
 * Detect workspace root by traversing upward from current directory
 */
function detectWorkspaceRoot(startPath: string): string | null {
	let currentPath = resolve(startPath);
	const maxIterations = 50;
	let iterations = 0;

	while (iterations < maxIterations) {
		iterations++;

		// Check for workspace markers
		const hasGit = existsSync(resolve(currentPath, ".git"));
		const hasPackageJson = existsSync(resolve(currentPath, "package.json"));
		const hasVreko = existsSync(resolve(currentPath, ".vreko"));

		if (hasGit || hasPackageJson || hasVreko) {
			return currentPath;
		}

		// Move up one directory
		const parent = resolve(currentPath, "..");
		if (parent === currentPath) {
			// Reached filesystem root
			break;
		}

		currentPath = parent;
	}

	return null;
}

/**
 * Find CLI path for local dev mode
 * Tries common locations relative to current directory
 */
function findCliPath(): string | undefined {
	const cwd = process.cwd();

	// Try common paths
	const candidates = [
		resolve(cwd, "apps/cli/dist/index.js"), // Monorepo
		resolve(cwd, "dist/index.js"), // Direct CLI repo
		resolve(cwd, "../cli/dist/index.js"), // Sibling directory
		resolve(cwd, "../../apps/cli/dist/index.js"), // Nested monorepo
	];

	for (const path of candidates) {
		if (existsSync(path)) {
			return path;
		}
	}

	return undefined;
}
