/**
 * Identity Module for MCP Config
 *
 * §10.2: Manages persistent identifiers for managed MCP config entries:
 * - userId: Stable user identifier (persists across reinstalls on same machine)
 * - installId: Per-installation identifier (regenerated on reinstall)
 *
 * @packageDocumentation
 */

import { randomUUID } from "node:crypto";
import { copyFileSync, existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

import type { AIClientFormat, VrekoManagedMetadata } from "./types.js";

// =============================================================================
// PATHS
// =============================================================================

/**
 * Get Vreko config directory path (primary)
 */
export function getVrekoConfigDir(): string {
	const isWindows = process.platform === "win32";
	if (isWindows) {
		return join(process.env.APPDATA || homedir(), "Vreko");
	}
	return join(homedir(), ".vreko");
}

/**
 * Get config directory with automatic migration from ~/.snapback to ~/.vreko.
 *
 * On first use: if ~/.vreko/ does not exist but ~/.snapback/ exists (and is a real
 * directory, not a symlink), seeds ~/.vreko/ by copying identity.json.
 *
 * Security (T-07.1-03-03): validates that oldDir is a real directory before reading.
 */
export function getConfigDirWithMigration(): string {
	const newDir = getVrekoConfigDir();
	// oldDir is the legacy snapback config path (migration source)
	const oldDir = join(homedir(), ".snapback");

	if (!existsSync(newDir) && existsSync(oldDir)) {
		try {
			// Validate oldDir is a real directory, not a symlink (T-07.1-03-03)
			const stat = statSync(oldDir);
			if (stat.isDirectory() && !stat.isSymbolicLink()) {
				mkdirSync(newDir, { recursive: true });
				const oldIdentity = join(oldDir, "identity.json");
				if (existsSync(oldIdentity)) {
					copyFileSync(oldIdentity, join(newDir, "identity.json"));
				}
			}
		} catch {
			// Migration is best-effort  -  if it fails, just use the new dir
		}
	}

	return newDir;
}

/**
 * Get identity file path
 */
function getIdentityFilePath(): string {
	return join(getVrekoConfigDir(), "identity.json");
}

// =============================================================================
// IDENTITY TYPES
// =============================================================================

interface StoredIdentity {
	/** User ID - stable across sessions */
	userId: string;
	/** Install ID - per machine install */
	installId: string;
	/** Created timestamp */
	createdAt: string;
}

// =============================================================================
// IDENTITY MANAGEMENT
// =============================================================================

/** Cached identity to avoid repeated disk reads */
let cachedIdentity: StoredIdentity | null = null;

/**
 * Get or create stored identity
 *
 * §5.2: Generates and persists userId and installId
 */
export function getOrCreateIdentity(): StoredIdentity {
	if (cachedIdentity) {
		return cachedIdentity;
	}

	const identityPath = getIdentityFilePath();

	// Try to read existing identity
	if (existsSync(identityPath)) {
		try {
			const content = readFileSync(identityPath, "utf-8");
			const identity = JSON.parse(content) as StoredIdentity;
			if (identity.userId && identity.installId) {
				cachedIdentity = identity;
				return identity;
			}
		} catch {
			// Invalid file, will regenerate
		}
	}

	// Create new identity
	const identity: StoredIdentity = {
		userId: randomUUID(),
		installId: randomUUID(),
		createdAt: new Date().toISOString(),
	};

	// Ensure directory exists
	const configDir = getVrekoConfigDir();
	mkdirSync(configDir, { recursive: true });

	// Write identity file
	writeFileSync(identityPath, JSON.stringify(identity, null, 2));

	cachedIdentity = identity;
	return identity;
}

/**
 * Get current CLI version from package.json
 */
function getCLIVersion(): string {
	try {
		// Try to read from node_modules or nearby package.json
		const packagePaths = [
			join(__dirname, "../package.json"),
			join(__dirname, "../../package.json"),
			join(process.cwd(), "package.json"),
		];

		for (const pkgPath of packagePaths) {
			if (existsSync(pkgPath)) {
				const content = readFileSync(pkgPath, "utf-8");
				const pkg = JSON.parse(content);
				if (pkg.name?.includes("vreko") || pkg.name?.includes("vreko")) {
					return pkg.version || "1.0.0";
				}
			}
		}
	} catch {
		// Fallback
	}
	return "1.0.0";
}

// =============================================================================
// MANAGED METADATA
// =============================================================================

/**
 * Generate managed metadata for MCP config entries
 *
 * §10.2: Creates the vrekoManaged object for config entries
 *
 * @param client - Target client
 * @param options - Additional options
 * @returns Managed metadata object
 */
export function createManagedMetadata(
	client: AIClientFormat | "other",
	options: {
		workspaceId?: string;
		transport: "stdio" | "stdio-shim" | "http";
	},
): VrekoManagedMetadata {
	const identity = getOrCreateIdentity();

	return {
		userId: identity.userId,
		installId: identity.installId,
		client,
		workspaceId: options.workspaceId,
		cliVersion: getCLIVersion(),
		updatedAt: new Date().toISOString(),
		transport: options.transport,
	};
}

/**
 * Check if a managed metadata object belongs to this installation
 *
 * §10.3: Used to determine if we can auto-modify an entry
 *
 * @param metadata - Metadata from existing config entry
 * @returns True if this install owns the entry
 */
export function isOwnedByThisInstall(metadata: VrekoManagedMetadata | undefined): boolean {
	if (!metadata?.installId) {
		return false;
	}

	const identity = getOrCreateIdentity();
	return metadata.installId === identity.installId;
}

/**
 * Reset cached identity (for testing)
 */
export function resetIdentityCache(): void {
	cachedIdentity = null;
}
