/**
 * MCP Config Validation Module
 *
 * Validates MCP configurations and detects common issues.
 * Provides detailed diagnostics for troubleshooting.
 *
 * @packageDocumentation
 */

import { execSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";

import type { AIClientConfig, MCPServerConfig } from "./types.js";

function isVrekoServerName(name: string, format?: AIClientConfig["format"]): boolean {
	if (name === "vreko") {
		return true;
	}

	if (format && name === `vreko-${format}`) {
		return true;
	}

	return name.startsWith("vreko-");
}

// =============================================================================
// TYPES
// =============================================================================

export interface ValidationIssue {
	/** Severity of the issue */
	severity: "error" | "warning" | "info";
	/** Issue code for programmatic handling */
	code: string;
	/** Human-readable message */
	message: string;
	/** Suggested fix */
	fix?: string;
}

export interface ValidationResult {
	/** Whether the config is valid */
	valid: boolean;
	/** List of issues found */
	issues: ValidationIssue[];
	/** The parsed vreko config (if found) */
	config?: MCPServerConfig;
}

export interface WorkspaceValidation {
	/** Whether workspace path exists */
	exists: boolean;
	/** Whether workspace has markers (.git, package.json, .vreko) */
	hasMarkers: boolean;
	/** Workspace path being validated */
	path?: string;
}

// =============================================================================
// VALIDATION FUNCTIONS
// =============================================================================

/**
 * Validate an AI client's MCP configuration
 *
 * @param client - The client to validate
 * @returns Validation result with issues
 *
 * @example
 * ```ts
 * const client = getClient('qoder');
 * const result = validateClientConfig(client);
 *
 * if (!result.valid) {
 *   for (const issue of result.issues) {
 *     console.error(`${issue.severity}: ${issue.message}`);
 *     if (issue.fix) process.stdout.write(`Fix: ${issue.fix}`);
 *   }
 * }
 * ```
 */
export function validateClientConfig(client: AIClientConfig): ValidationResult {
	const issues: ValidationIssue[] = [];

	// Check if config file exists
	if (!existsSync(client.configPath)) {
		issues.push({
			severity: "error",
			code: "CONFIG_NOT_FOUND",
			message: `Config file not found: ${client.configPath}`,
			fix: `Run: vreko tools configure --${client.name}`,
		});
		return { valid: false, issues };
	}

	// Try to read and parse config
	let configContent: string;
	let parsedConfig: unknown;

	try {
		configContent = readFileSync(client.configPath, "utf-8");
	} catch (error) {
		issues.push({
			severity: "error",
			code: "CONFIG_READ_ERROR",
			message: `Cannot read config file: ${error instanceof Error ? error.message : "Unknown error"}`,
			fix: "Check file permissions",
		});
		return { valid: false, issues };
	}

	try {
		parsedConfig = JSON.parse(configContent);
	} catch (error) {
		issues.push({
			severity: "error",
			code: "CONFIG_PARSE_ERROR",
			message: `Invalid JSON in config file: ${error instanceof Error ? error.message : "Unknown error"}`,
			fix: `Edit ${client.configPath} to fix JSON syntax, or run: vreko tools configure --${client.name} --force`,
		});
		return { valid: false, issues };
	}

	// Check if Vreko is configured
	if (!client.hasVreko) {
		issues.push({
			severity: "warning",
			code: "VREKO_NOT_CONFIGURED",
			message: "Vreko MCP server not found in config",
			fix: `Run: vreko tools configure --${client.name}`,
		});
		return { valid: false, issues };
	}

	// Extract vreko config based on format
	const vrekoConfig = extractVrekoConfig(parsedConfig, client.format);
	if (!vrekoConfig) {
		issues.push({
			severity: "error",
			code: "VREKO_CONFIG_INVALID",
			message: "Vreko config found but cannot be parsed",
		});
		return { valid: false, issues };
	}

	// Validate vreko config structure
	validateVrekoConfig(vrekoConfig, issues);

	// Validate workspace path if present
	if (vrekoConfig.command && vrekoConfig.args) {
		const workspaceIdx = vrekoConfig.args.indexOf("--workspace");
		if (workspaceIdx !== -1 && workspaceIdx + 1 < vrekoConfig.args.length) {
			const workspacePath = vrekoConfig.args[workspaceIdx + 1];
			const wsValidation = validateWorkspacePath(workspacePath);

			if (!wsValidation.exists) {
				issues.push({
					severity: "error",
					code: "WORKSPACE_NOT_FOUND",
					message: `Workspace path does not exist: ${workspacePath}`,
					fix: "Update workspace path or run: vreko tools configure --force",
				});
			} else if (!wsValidation.hasMarkers) {
				issues.push({
					severity: "warning",
					code: "WORKSPACE_NO_MARKERS",
					message: `Workspace path has no markers (.git, package.json, .vreko): ${workspacePath}`,
					fix: "Run: vreko init",
				});
			}
		}
	}

	return {
		valid: issues.filter((i) => i.severity === "error").length === 0,
		issues,
		config: vrekoConfig,
	};
}

/**
 * Validate workspace path
 */
export function validateWorkspacePath(workspacePath: string): WorkspaceValidation {
	const absPath = resolve(workspacePath);

	if (!existsSync(absPath)) {
		return { exists: false, hasMarkers: false, path: absPath };
	}

	// Check for workspace markers
	const hasGit = existsSync(resolve(absPath, ".git"));
	const hasPackageJson = existsSync(resolve(absPath, "package.json"));
	const hasVreko = existsSync(resolve(absPath, ".vreko"));

	return {
		exists: true,
		hasMarkers: hasGit || hasPackageJson || hasVreko,
		path: absPath,
	};
}

// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

/**
 * Extract Vreko config from parsed config file
 */
function extractVrekoConfig(parsed: unknown, format: AIClientConfig["format"]): MCPServerConfig | null {
	if (!parsed || typeof parsed !== "object") {
		return null;
	}

	const config = parsed as Record<string, unknown>;

	switch (format) {
		case "vscode":
			// VS Code .vscode/mcp.json uses "servers" key, not "mcpServers"
			if ("servers" in config && typeof config.servers === "object" && config.servers !== null) {
				const servers = config.servers as Record<string, unknown>;
				for (const [name, server] of Object.entries(servers)) {
					if (isVrekoServerName(name, format) && typeof server === "object" && server !== null) {
						return server as MCPServerConfig;
					}
				}
			}
			return null;

		case "claude":
		case "cursor":
		case "windsurf":
		case "cline":
		case "roo-code":
		case "qoder":
		case "gemini":
		case "zed":
		case "claude-code":
			// Standard mcpServers format
			if ("mcpServers" in config && typeof config.mcpServers === "object" && config.mcpServers !== null) {
				const servers = config.mcpServers as Record<string, unknown>;
				// Check namespaced key first
				for (const [name, server] of Object.entries(servers)) {
					if (isVrekoServerName(name, format) && typeof server === "object" && server !== null) {
						return server as MCPServerConfig;
					}
				}
			}
			return null;

		case "continue":
			// Continue uses experimental.modelContextProtocolServers array
			if ("experimental" in config && typeof config.experimental === "object" && config.experimental !== null) {
				const experimental = config.experimental as Record<string, unknown>;
				if (
					"modelContextProtocolServers" in experimental &&
					Array.isArray(experimental.modelContextProtocolServers)
				) {
					const server = experimental.modelContextProtocolServers.find(
						(s: unknown) =>
							typeof s === "object" &&
							s !== null &&
							typeof (s as Record<string, unknown>).name === "string" &&
							isVrekoServerName((s as Record<string, unknown>).name as string),
					);
					return server ? (server as MCPServerConfig) : null;
				}
			}
			return null;

		default:
			return null;
	}
}

/**
 * Validate Vreko config structure
 */
function validateVrekoConfig(config: MCPServerConfig, issues: ValidationIssue[]): void {
	// Must have either command or url
	if (!config.command && !config.url) {
		issues.push({
			severity: "error",
			code: "MISSING_COMMAND_OR_URL",
			message: "Config must have either 'command' (stdio) or 'url' (HTTP)",
			fix: "Run: vreko tools configure --force",
		});
		return;
	}

	// If using stdio transport (command), validate structure
	if (config.command) {
		// CRITICAL: Validate that command is executable
		if (!isCommandExecutable(config.command)) {
			issues.push({
				severity: "error",
				code: "COMMAND_NOT_EXECUTABLE",
				message: `Command not found or not executable: ${config.command}`,
				fix: "Run: vreko tools repair (will auto-fix node path)",
			});
		}

		if (!config.args || !Array.isArray(config.args)) {
			issues.push({
				severity: "error",
				code: "MISSING_ARGS",
				message: "Command-based config must have 'args' array",
				fix: "Run: vreko tools configure --force",
			});
		} else {
			// Check for required args
			if (!config.args.includes("mcp")) {
				issues.push({
					severity: "error",
					code: "MISSING_MCP_ARG",
					message: "Args must include 'mcp' command",
					fix: "Run: vreko tools configure --force",
				});
			}

			if (!config.args.includes("--stdio")) {
				issues.push({
					severity: "error",
					code: "MISSING_STDIO_ARG",
					message: "Args must include '--stdio' flag",
					fix: "Run: vreko mcp repair --client <name>",
				});
			}

			// Check for deprecated 'shim' command (removed in favor of --stdio)
			if (config.args.includes("shim")) {
				issues.push({
					severity: "error",
					code: "DEPRECATED_SHIM_COMMAND",
					message: "Args contain deprecated 'shim' command - use '--stdio' instead",
					fix: "Run: vreko mcp repair --client <name>",
				});
			}

			// Warn if missing workspace
			if (!config.args.includes("--workspace")) {
				issues.push({
					severity: "warning",
					code: "MISSING_WORKSPACE_ARG",
					message: "Args should include '--workspace' path for reliability",
					fix: "Run: vreko tools configure --force",
				});
			}

			// Validate CLI path exists (first arg after command)
			if (config.args.length > 0) {
				const cliPath = config.args[0];
				if (cliPath?.endsWith(".js") && !existsSync(cliPath)) {
					issues.push({
						severity: "error",
						code: "CLI_PATH_NOT_FOUND",
						message: `CLI script not found: ${cliPath}`,
						fix: "Rebuild CLI: pnpm --filter @vreko/cli build",
					});
				}
			}
		}
	}

	// If using HTTP transport (url), validate
	if (config.url) {
		try {
			new URL(config.url);
		} catch {
			issues.push({
				severity: "error",
				code: "INVALID_URL",
				message: `Invalid server URL: ${config.url}`,
				fix: "Run: vreko tools configure --force",
			});
		}
	}

	// Check for API key or workspace ID in env
	if (config.env) {
		if (!config.env.VREKO_API_KEY && !config.env.VREKO_WORKSPACE_ID) {
			issues.push({
				severity: "info",
				code: "NO_AUTH",
				message: "No API key or workspace ID found (free tier will be used)",
			});
		}
	}
}

/**
 * Check if a command is executable (exists in PATH or is absolute path)
 *
 * @param command - Command to check
 * @returns True if command is likely executable
 */
function isCommandExecutable(command: string): boolean {
	// If it's an absolute path, check if file exists
	if (command.startsWith("/") || command.match(/^[A-Z]:\\/i)) {
		return existsSync(command);
	}

	// For relative commands, try to find them
	try {
		const isWindows = process.platform === "win32";
		const cmd = isWindows ? `where ${command}` : `which ${command}`;
		execSync(cmd, { encoding: "utf-8", timeout: 5000 });
		return true;
	} catch {
		return false;
	}
}
